/**
 * One file, directory or symlink. Size, mode, owner and times describe what
 * the entry resolves to, so a symlink to a file reports the file's; a
 * dangling symlink reports the link itself.
 */
export interface FsEntry {
  /** base name */
  name: Uint8Array;
  /** the path as given, or the listed directory joined with `name` */
  path: Uint8Array;
  /** the entry itself: a symlink is SYMLINK */
  type: FsEntryType;
  /**
   * What the entry resolves to after following symlinks: the same as `type`
   * for anything but a symlink, UNSPECIFIED when a symlink dangles or loops.
   */
  targetType: FsEntryType;
  size: number;
  /** permission bits, e.g. 0o644 */
  mode: number;
  /**
   * Modification time in nanoseconds since the Unix epoch. Too large for a
   * JavaScript number, so JavaScript code generators read it as a string.
   */
  mtimeNs: string;
  uid: number;
  gid: number;
  /** what a symlink points to, as stored; empty otherwise */
  symlinkTarget: Uint8Array;
}

export interface FsReadRequest {
  /** machine name or id */
  vmId: string;
  path: Uint8Array;
  /** first byte to read */
  offset: number;
  /** bytes to read from `offset`; unset reads to the end */
  length?: number | undefined;
}

export interface FsReadChunk {
  /** first chunk only */
  entry?: FsEntry | undefined;
  data: Uint8Array;
  /** last chunk: everything was sent */
  eof: boolean;
  /** on the last chunk: total bytes sent */
  bytesRead: number;
}

/**
 * The first chunk sets `vm_id`, `path` and the options; every chunk may carry
 * data. Closing the stream ends the file, so an empty file is one chunk with
 * no data.
 */
export interface FsWriteChunk {
  /** machine name or id */
  vmId: string;
  path: Uint8Array;
  /**
   * Permission bits for the file. Unset keeps an existing file's mode and
   * gives a new one 0o644.
   */
  mode?:
    | number
    | undefined;
  /**
   * When set, the write fails with `size_mismatch` and leaves the file as it
   * was unless exactly this many bytes arrive.
   */
  expectedSize?: number | undefined;
  data: Uint8Array;
}

export interface FsWriteResponse {
  bytesWritten: number;
  /** the file as written (the symlink's target when writing through one) */
  entry?: FsEntry | undefined;
}

