export interface SnapshotInfo {
  snapshotId: string;
  name: string;
  /** current (latest ready) version; 0 = none yet */
  version: number;
  /** "pending" | "ready" | "failed" */
  status: string;
  sizeBytes: number;
  /** epoch MILLISECONDS; moves with every new version */
  updatedAt: number;
  vcpu: number;
  memoryBytes: number;
  useCount: number;
  /**
   * Wall-clock unix epoch MILLISECONDS the snapshot was first captured
   * (`updated_at` above moves with every new version; this one does not).
   */
  createdAt: number;
  /**
   * Highest version whose save failed (0 = none), and why. A save of version
   * N failed iff failed_version >= N; `version` stays on the last ready one,
   * and `status` is "failed" only when there is no ready version at all.
   */
  failedVersion: number;
  failureReason: string;
  /**
   * Where the snapshot's bytes are. "local": on a worker's disk.
   * "archiving": being copied to object storage. "archived": in object
   * storage only. "unarchiving": being restored to a worker's disk. Machines
   * can't be created from it, nor can it be saved again, unless it is local;
   * `archived` is true for the other three.
   */
  archived: boolean;
  storage: string;
}

